// W0-05a: fetch + verify + publication-state rules for demo packages. The wire
// shape and the registry live in `./schema.ts`; this module decides what a
// screen may render from a package. It fails closed on every path: an invalid,
// unsigned, hash-mismatched, unapproved, superseded or revoked package never
// yields playable media, and a missing or unconfigured mirror yields the locked
// `footage-pending` state — never a network guess, never a stand-in clip.
//
// The package is served from a same-origin mirror at
// `<mirrorUrl>/demos/<scenarioId>.json`, regenerated by L9 at build time. The
// mirror URL comes from config alone; there is no default host and no second
// fetch path for the same endpoint.
//
// Cache contract: entries store the raw body so every read re-verifies the
// hash and re-runs the full parse and publication gates — a cached package can
// only ever play through the same rules a fresh fetch passes. `markForPurge`
// flags the entry; deleting the cached media files is the host's job, while the
// small record stays so an offline screen can keep saying why playback stopped.

import { isRfc3339 } from '../release/schema';
import {
  isScenarioId,
  parseDemoPackage,
  type DemoInteractive,
  type DemoPackage,
  type DemoProblem,
  type DemoRendition,
  type ScenarioRegistry,
} from './schema';

const HEX64 = /^[0-9a-f]{64}$/;

/** SHA-256 over UTF-8 bytes, via the platform's Web Crypto (no node: imports). */
async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  let hex = '';
  for (const byte of new Uint8Array(digest)) hex += byte.toString(16).padStart(2, '0');
  return hex;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Why a package was refused, on top of the schema's own problem codes. */
export type InvalidReason =
  | DemoProblem
  | 'hash-mismatch'
  | 'captions-required'
  | 'approval-incomplete'
  | 'scenario-mismatch';

/** The media an approved package may hand a player. */
export type DemoMedia = {
  renditions: readonly DemoRendition[];
  posterUrl: string;
  interactive: DemoInteractive | null;
};

/**
 * The presentation union W0-05b's player renders. Exact shapes matter: an
 * `invalid`, `footage-pending` or `superseded` state carries no URL a screen
 * could turn into playback, and `revoked` carries only the transcript.
 */
export type DemoPresentation =
  | {
      state: 'playable';
      scenarioId: string;
      packageRevision: string;
      sourceRevision: string;
      contentHash: string;
      source: 'network' | 'cache';
      fetchedAt: number;
      media: DemoMedia;
      captionsUrl: string;
      transcriptUrl: string;
    }
  | { state: 'footage-pending'; reason: 'footage-pending' }
  | { state: 'superseded'; reason: 'superseded' }
  | { state: 'revoked'; reason: 'revoked'; transcriptUrl: string | null; purgeCached: true }
  | { state: 'invalid'; reason: InvalidReason };

export type CachedDemo = {
  package: DemoPackage;
  /** The raw body exactly as fetched, so a cache read re-verifies the hash. */
  rawText: string;
  fetchedAt: number;
};

export type DemoCache = {
  get(scenarioId: string): CachedDemo | undefined;
  put(scenarioId: string, entry: CachedDemo): void;
  /** Marks the entry's cached media for deletion; the host performs the purge. */
  markForPurge(scenarioId: string): void;
};

/**
 * An in-memory cache for hosts without one. Purged entries keep their record
 * (so an offline screen can still explain a revocation) but are flagged via
 * `isMarkedForPurge`.
 */
export function createMemoryDemoCache(): DemoCache & { isMarkedForPurge(scenarioId: string): boolean } {
  const entries = new Map<string, CachedDemo>();
  const purged = new Set<string>();
  return {
    get: (scenarioId) => entries.get(scenarioId),
    put: (scenarioId, entry) => {
      entries.set(scenarioId, entry);
    },
    markForPurge: (scenarioId) => {
      purged.add(scenarioId);
    },
    isMarkedForPurge: (scenarioId) => purged.has(scenarioId),
  };
}

/** The one request shape this client makes; injectable for tests and SSR. */
export type FetchLike = (url: string) => Promise<{
  ok: boolean;
  status: number;
  text: () => Promise<string>;
}>;

export type DemoResolverConfig = {
  /** Absolute https origin of the same-origin mirror. Absent/unsafe → footage-pending, no fetch. */
  mirrorUrl?: string;
  fetchImpl?: FetchLike;
  now?: () => number;
  cache?: DemoCache;
};

export type DemoResolver = ReturnType<typeof createDemoResolver>;

export function createDemoResolver(config: DemoResolverConfig = {}) {
  const rawMirror = typeof config.mirrorUrl === 'string' ? config.mirrorUrl.trim().replace(/\/+$/, '') : '';
  // A mirror that is not an https origin is a configuration error, and the
  // answer to a configuration error is footage-pending — never a fetch.
  const mirrorUrl = rawMirror.startsWith('https://') && rawMirror.length > 'https://'.length ? rawMirror : null;
  const fetchImpl: FetchLike = config.fetchImpl ?? ((url: string) => fetch(url));
  const now = config.now ?? (() => Date.now());
  const cache = config.cache ?? createMemoryDemoCache();
  const footagePending: DemoPresentation = { state: 'footage-pending', reason: 'footage-pending' };

  /** Hash gate → parse gate → mirror-label gate, in that order. */
  async function verified(rawText: string, scenarioId: string): Promise<{ package: DemoPackage } | { problem: InvalidReason }> {
    let json: unknown;
    try {
      json = JSON.parse(rawText);
    } catch {
      return { problem: 'not-an-object' };
    }
    if (
      isRecord(json) &&
      typeof json.contentHash === 'string' &&
      HEX64.test(json.contentHash.trim().toLowerCase())
    ) {
      // contentHash covers the body with its own key removed; a digest cannot
      // cover itself. The comparison is the integrity gate, so it runs before
      // the body is interpreted any further.
      const rest: Record<string, unknown> = { ...json };
      delete rest.contentHash;
      if ((await sha256Hex(JSON.stringify(rest))) !== json.contentHash.trim().toLowerCase()) {
        return { problem: 'hash-mismatch' };
      }
    }
    const parsed = parseDemoPackage(json);
    if ('problem' in parsed) return { problem: parsed.problem };
    // The mirror labels the file by path; the body must agree with the label.
    if (parsed.package.scenarioId !== scenarioId) return { problem: 'scenario-mismatch' };
    return { package: parsed.package };
  }

  function present(pkg: DemoPackage, source: 'network' | 'cache', fetchedAt: number): DemoPresentation {
    switch (pkg.publicationState) {
      case 'pending':
        // Footage pending is the honest state for the whole front door today:
        // nothing plays until an approved package exists.
        return footagePending;
      case 'superseded':
        // A superseded package plays only as labelled historical proof and
        // never under the old URL. Nothing in the package tells the front door
        // which surface is the labelled one, so the presentation carries no
        // media at all — a named state a screen can render, and nothing to play.
        return { state: 'superseded', reason: 'superseded' };
      case 'revoked':
        // Playback stops, the transcript stays readable, and whatever the host
        // cached for this scenario is marked for purge.
        cache.markForPurge(pkg.scenarioId);
        return {
          state: 'revoked',
          reason: 'revoked',
          transcriptUrl: pkg.transcriptUrl,
          purgeCached: true,
        };
      case 'approved': {
        if (pkg.captionsUrl === null || pkg.transcriptUrl === null) {
          // Half-rendered accessibility is not accessibility: captions and the
          // transcript ship together or the package does not play.
          return { state: 'invalid', reason: 'captions-required' };
        }
        if (
          pkg.approval.watchedComplete !== true ||
          pkg.approval.approvedBy === '' ||
          !isRfc3339(pkg.approval.approvedAt)
        ) {
          return { state: 'invalid', reason: 'approval-incomplete' };
        }
        return {
          state: 'playable',
          scenarioId: pkg.scenarioId,
          packageRevision: pkg.packageRevision,
          sourceRevision: pkg.sourceRevision,
          contentHash: pkg.contentHash,
          source,
          fetchedAt,
          media: { renditions: pkg.renditions, posterUrl: pkg.posterUrl, interactive: pkg.interactive },
          captionsUrl: pkg.captionsUrl,
          transcriptUrl: pkg.transcriptUrl,
        };
      }
    }
  }

  async function resolve(scenarioId: string): Promise<DemoPresentation> {
    // A deep link can carry anything; only a shaped scenario id may reach the
    // mirror, and an unconfigured mirror is answered from what is already
    // known: footage-pending.
    if (!isScenarioId(scenarioId) || mirrorUrl === null) return footagePending;
    let rawText: string | null = null;
    try {
      const response = await fetchImpl(`${mirrorUrl}/demos/${scenarioId}.json`);
      if (!response.ok) {
        // The mirror answered: nothing is published for this scenario today.
        return footagePending;
      }
      rawText = await response.text();
    } catch {
      // Offline: fall through to the cache.
    }
    if (rawText === null) {
      const entry = cache.get(scenarioId);
      if (entry === undefined) return footagePending;
      const cached = await verified(entry.rawText, scenarioId);
      if ('problem' in cached) return { state: 'invalid', reason: cached.problem };
      return present(cached.package, 'cache', entry.fetchedAt);
    }
    const verdict = await verified(rawText, scenarioId);
    if ('problem' in verdict) return { state: 'invalid', reason: verdict.problem };
    const entry: CachedDemo = { package: verdict.package, rawText, fetchedAt: now() };
    cache.put(scenarioId, entry);
    return present(verdict.package, 'network', entry.fetchedAt);
  }

  return { resolve };
}

export type EnginesIndexRow = {
  scenarioId: string;
  engine: string;
  title: string;
  oneLiner: string;
  posterAlt: string;
  order: number;
};

/**
 * The /engines index is built from the registry alone. A scenario the registry
 * does not name is `unlisted` — still playable by deep link (resolve() never
 * consults the registry), absent from the index rows, and never silently
 * dropped: it comes back named in `unlisted`.
 */
export function buildEnginesIndex(
  registry: ScenarioRegistry,
  scenarioIds: readonly string[],
): { rows: EnginesIndexRow[]; unlisted: string[] } {
  const byId = new Map(registry.map((row) => [row.scenarioId, row] as const));
  const rows: EnginesIndexRow[] = [];
  const unlisted: string[] = [];
  for (const scenarioId of scenarioIds) {
    const row = byId.get(scenarioId);
    if (row === undefined) {
      unlisted.push(scenarioId);
      continue;
    }
    rows.push({
      scenarioId: row.scenarioId,
      engine: row.engine,
      title: row.title,
      oneLiner: row.oneLiner,
      posterAlt: row.posterAlt,
      order: row.order,
    });
  }
  rows.sort((a, b) => a.order - b.order);
  return { rows, unlisted };
}
